{const _p=portrait;portrait=function(L,size=160,key){if(key&&AVS[key]){const k='av_'+key+size;if(PCACHE[k])return PCACHE[k];const c=document.createElement('canvas');c.width=c.height=size;drawAvatar(c,key);return PCACHE[k]=c;}return _p(L,size,key);};}
/* =====================================================================
   AVATAR ẢNH THẬT (3D realistic): ảnh do người dùng cung cấp cho từng nhân vật.
   Nhân vật chưa có ảnh dùng chân dung vẽ (w_avatar.js). Có thể đổi ảnh trong Thư viện nhân vật (lưu trên trình duyệt).
   ===================================================================== */
const AV_IMG={
 melania:'data:image/jpeg;base64,',
 natasha:'data:image/jpeg;base64,',
 lucy:'data:image/jpeg;base64,',
 sara:'data:image/jpeg;base64,',
 laura:'data:image/jpeg;base64,',
 bancroft:'data:image/jpeg;base64,',
 jeanie:'data:image/jpeg;base64,',
 rossie:'data:image/jpeg;base64,',
 lily:'data:image/jpeg;base64,',
 evan:'data:image/jpeg;base64,',
 ethan:'data:image/jpeg;base64,'
};
const AV_EL={};
function avLS(id){try{return localStorage.getItem('ra_av_'+id);}catch(e){return null;}}
function avLoad(id){const src=avLS(id)||AV_IMG[id];if(!src){delete AV_EL[id];return;}const im=new Image();im.onload=()=>{AV_EL[id]=im;for(const k in PCACHE)if(k.startsWith('img_'+id+'_'))delete PCACHE[k];if(id==='ethan'){try{const pv=document.getElementById('pav');pv.getContext('2d').clearRect(0,0,pv.width,pv.height);pv.getContext('2d').drawImage(portrait(ETHAN,92,'ethan'),0,0);}catch(e){}}};im.src=src;}
NPCS.forEach(n=>avLoad(n.id));avLoad('ethan');
{const _p=portrait;portrait=function(L,size=160,key){const im=key&&AV_EL[key];if(im){const k='img_'+key+'_'+size;if(PCACHE[k])return PCACHE[k];
  const c=document.createElement('canvas');c.width=c.height=size;const g=c.getContext('2d');const s=Math.min(im.width,im.height);
  g.drawImage(im,(im.width-s)/2,(im.height-s)/2,s,s,0,0,size,size);return PCACHE[k]=c;}
 return _p(L,size,key);};}
function avPick(id){const inp=document.createElement('input');inp.type='file';inp.accept='image/*';inp.onchange=()=>{const f=inp.files[0];if(!f)return;const r=new FileReader();
 r.onload=()=>{const im=new Image();im.onload=()=>{const c=document.createElement('canvas');c.width=c.height=384;const s=Math.min(im.width,im.height);
  c.getContext('2d').drawImage(im,(im.width-s)/2,(im.height-s)/2,s,s,0,0,384,384);const url=c.toDataURL('image/jpeg',.85);
  try{localStorage.setItem('ra_av_'+id,url);}catch(e){toast('Trình duyệt không cho lưu ảnh, ảnh chỉ dùng tạm trong lần chơi này.');}
  AV_EL[id]=im;const im2=new Image();im2.onload=()=>{AV_EL[id]=im2;for(const k in PCACHE)if(k.startsWith('img_'+id+'_'))delete PCACHE[k];library(id);};im2.src=url;};im.src=r.result;};r.readAsDataURL(f);};inp.click();}
function avReset(id){try{localStorage.removeItem('ra_av_'+id);}catch(e){}for(const k in PCACHE)if(k.startsWith('img_'+id+'_'))delete PCACHE[k];delete AV_EL[id];avLoad(id);setTimeout(()=>library(id),150);}
{const _l=library;library=function(sel){_l(sel);const id=library.last,lp=mbox.querySelector('#lp');if(!id||!lp||lp.querySelector('.avbtn'))return;
 const w=document.createElement('div');w.className='avbtn';w.style.cssText='display:flex;gap:6px;justify-content:center;margin-top:6px';
 const b=document.createElement('button');b.textContent='🖼 Đổi ảnh';b.onclick=()=>avPick(id);w.appendChild(b);
 if(avLS(id)){const r=document.createElement('button');r.textContent='↺ Ảnh gốc';r.onclick=()=>avReset(id);w.appendChild(r);}
 lp.appendChild(w);};}
